+    public void testCosineInvariant() throws Exception {
+        int dim = 4;
+        int L = 1;
+        int n = 100;
+        String fieldName = "vector";
+        Supplier<float[]> vectorValue = () -> new float[] { randomFloat(), randomFloat(), randomFloat(), randomFloat() };
+        try (Directory d = newDirectory()) {
